import type { ThemeId, ThemeMode } from './ids';

/**
 * The TS half of a role theme. Colors live in CSS (src/styles/role-themes.css)
 * — this object only carries what JS/SSR needs: the mode the palette was
 * designed for, the browser chrome color and the corner language.
 */
export interface RoleTheme {
  id: ThemeId;
  label: string;
  /** Used when site.config theme.mode is "system" is not decisive (e.g. metadata). */
  defaultMode: ThemeMode;
  /** sRGB of --bg per mode — generated by `npm run contrast`. */
  themeColor: Record<ThemeMode, string>;
  corners: 'sharp' | 'rounded';
}
